// MULENET_NETWORK=undeployed tsx src/main.ts
// Local: the genesis wallet is the only sponsor wallet. Preprod: the pool comes from
// infra/.env.sponsors.preprod (SPONSOR_SEED_0..n), generated by packages/sdk/scripts/gen-sponsor-wallets.ts.
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fromHex } from '@mulenet/crypto';
import {
  GENESIS_SEED,
  addDustFeesAndFinalize,
  buildWallet,
  deserializeFinalized,
  ensureDust,
  networks,
  waitForSync,
  type WalletContext,
} from '@mulenet/sdk';
import { loadPublicConfig, repoRoot } from '@mulenet/sdk/config';
import type { FinalizedTransaction } from '@midnight-ntwrk/midnight-js-protocol/ledger';
import { createAccounting } from './accounting.js';
import { WalletPool } from './pool.js';
import { preflight } from './preflight.js';
import { ROLE_CIRCUITS, buildSponsor, type Role } from './server.js';

const network = (process.env.MULENET_NETWORK ?? 'undeployed') as 'undeployed' | 'preprod';
const cfg = loadPublicConfig(network);
const contractAddress =
  cfg.contractAddress ?? JSON.parse(readFileSync(resolve(repoRoot(), `infra/state/${network}.json`), 'utf8')).contractAddress;
const net = networks[network]();

const seeds =
  network === 'undeployed'
    ? [GENESIS_SEED]
    : readFileSync(resolve(repoRoot(), `infra/.env.sponsors.${network}`), 'utf8')
        .split('\n')
        .filter((l) => l.startsWith('SPONSOR_SEED_'))
        .map((l) => l.split('=')[1].trim());

const wallets: { id: string; wallet: WalletContext }[] = [];
for (const [i, seed] of seeds.entries()) {
  const wallet = await buildWallet(net, seed);
  await ensureDust(wallet);
  wallets.push({ id: `sponsor-${i}`, wallet });
}

// Sponsor-side TTL for the DUST offer; the binding deadline is the user's intent TTL (R3).
const feeTtl = () => new Date(Date.now() + 20 * 60_000);
const pool = new WalletPool<WalletContext, FinalizedTransaction>(
  wallets,
  async (w, tx) => w.wallet.submitTransaction(await addDustFeesAndFinalize(w, tx, feeTtl())),
  async (w) => void (await waitForSync(w)),
);

const allowed = new Set([...ROLE_CIRCUITS.institution, ...ROLE_CIRCUITS.guardian, ...ROLE_CIRCUITS.keeper]);
const callers = new Map<string, { publicKey: Uint8Array; role: Role }>([
  ...cfg.institutions.map((i) => [i.id, { publicKey: fromHex(i.signingPublicKey), role: 'institution' as Role }] as const),
  ...cfg.guardians.members.map((g) => [`guardian-${g.index}`, { publicKey: fromHex(g.signingPublicKey), role: 'guardian' as Role }] as const),
]);

const { app } = buildSponsor<FinalizedTransaction>({
  callers,
  inspect: (bytes) => {
    const tx = deserializeFinalized(bytes);
    return { tx, result: preflight(tx, { contractAddress, allowedCircuits: allowed }) };
  },
  pool: pool as WalletPool<unknown, FinalizedTransaction>,
  accounting: createAccounting({ dbPath: resolve(repoRoot(), `.data/${network}/sponsor.db`) }),
  windowMs: Number(process.env.SPONSOR_WINDOW_MS ?? (network === 'undeployed' ? 2_000 : 30_000)),
});
app.addHook('onClose', async () => {
  for (const w of wallets) await w.wallet.wallet.stop();
});
await app.listen({ host: process.env.HOST ?? '127.0.0.1', port: Number(process.env.PORT ?? new URL(cfg.sponsor.url).port) });
